CREATE TYPE "Difficulty" AS ENUM ('EASY','MEDIUM','HARD');
CREATE TYPE "OutputComparison" AS ENUM ('EXACT','TRIMMED','TOKENS','UNORDERED','CUSTOM');
CREATE TYPE "SubmissionStatus" AS ENUM ('PENDING','ACCEPTED','WRONG_ANSWER','COMPILATION_ERROR','RUNTIME_ERROR','TIME_LIMIT_EXCEEDED','MEMORY_LIMIT_EXCEEDED','INTERNAL_ERROR');
CREATE TYPE "ProgressStatus" AS ENUM ('UNATTEMPTED','GUIDED','INDEPENDENT','SOLVED');
CREATE TABLE "Problem" ("id" TEXT PRIMARY KEY,"slug" TEXT NOT NULL UNIQUE,"title" TEXT NOT NULL,"difficulty" "Difficulty" NOT NULL,"description" TEXT NOT NULL,"constraints" TEXT[] NOT NULL,"source" TEXT,"sourceUrl" TEXT,"externalProblemId" TEXT,"orderIndex" INTEGER NOT NULL DEFAULT 0,"isPublished" BOOLEAN NOT NULL DEFAULT false,"timeLimitMs" INTEGER NOT NULL DEFAULT 2000,"memoryLimitMb" INTEGER NOT NULL DEFAULT 256,"outputComparison" "OutputComparison" NOT NULL DEFAULT 'TRIMMED',"expectedTimeComplexity" TEXT,"expectedSpaceComplexity" TEXT,"canonicalPatterns" TEXT[] DEFAULT ARRAY[]::TEXT[],"prerequisiteTopics" TEXT[] DEFAULT ARRAY[]::TEXT[],"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "Topic" ("id" TEXT PRIMARY KEY,"name" TEXT NOT NULL UNIQUE,"slug" TEXT NOT NULL UNIQUE);
CREATE TABLE "ProblemTopic" ("problemId" TEXT NOT NULL,"topicId" TEXT NOT NULL,PRIMARY KEY("problemId","topicId"),FOREIGN KEY("problemId") REFERENCES "Problem"("id") ON DELETE CASCADE,FOREIGN KEY("topicId") REFERENCES "Topic"("id") ON DELETE CASCADE);
CREATE TABLE "ProblemExample" ("id" TEXT PRIMARY KEY,"problemId" TEXT NOT NULL,"input" TEXT NOT NULL,"output" TEXT NOT NULL,"explanation" TEXT,"orderIndex" INTEGER NOT NULL,UNIQUE("problemId","orderIndex"),FOREIGN KEY("problemId") REFERENCES "Problem"("id") ON DELETE CASCADE);
CREATE TABLE "ProblemTemplate" ("id" TEXT PRIMARY KEY,"problemId" TEXT NOT NULL,"language" TEXT NOT NULL,"languageVersion" TEXT NOT NULL,"starterCode" TEXT NOT NULL,"driverCode" TEXT NOT NULL,"functionName" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,UNIQUE("problemId","language"),FOREIGN KEY("problemId") REFERENCES "Problem"("id") ON DELETE CASCADE);
CREATE TABLE "TestCase" ("id" TEXT PRIMARY KEY,"problemId" TEXT NOT NULL,"input" TEXT NOT NULL,"expectedOutput" TEXT NOT NULL,"isHidden" BOOLEAN NOT NULL DEFAULT true,"orderIndex" INTEGER NOT NULL,"weight" INTEGER NOT NULL DEFAULT 1,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE("problemId","orderIndex"),FOREIGN KEY("problemId") REFERENCES "Problem"("id") ON DELETE CASCADE);
CREATE TABLE "Submission" ("id" TEXT PRIMARY KEY,"userId" TEXT NOT NULL,"problemId" TEXT NOT NULL,"language" TEXT NOT NULL,"sourceCode" TEXT NOT NULL,"status" "SubmissionStatus" NOT NULL DEFAULT 'PENDING',"runtimeMs" INTEGER,"memoryKb" INTEGER,"passedCases" INTEGER NOT NULL DEFAULT 0,"totalCases" INTEGER NOT NULL DEFAULT 0,"failedTestIndex" INTEGER,"diagnostic" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY("problemId") REFERENCES "Problem"("id") ON DELETE CASCADE);
CREATE TABLE "UserProblemProgress" ("id" TEXT PRIMARY KEY,"userId" TEXT NOT NULL,"problemId" TEXT NOT NULL,"status" "ProgressStatus" NOT NULL DEFAULT 'UNATTEMPTED',"attempts" INTEGER NOT NULL DEFAULT 0,"guidanceLevel" INTEGER NOT NULL DEFAULT 0,"lastAttemptAt" TIMESTAMP(3),"solvedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,UNIQUE("userId","problemId"),FOREIGN KEY("problemId") REFERENCES "Problem"("id") ON DELETE CASCADE);
CREATE INDEX "Problem_isPublished_orderIndex_idx" ON "Problem"("isPublished","orderIndex");
CREATE INDEX "Problem_difficulty_isPublished_idx" ON "Problem"("difficulty","isPublished");
CREATE INDEX "ProblemTopic_topicId_problemId_idx" ON "ProblemTopic"("topicId","problemId");
CREATE INDEX "TestCase_problemId_isHidden_orderIndex_idx" ON "TestCase"("problemId","isHidden","orderIndex");
CREATE INDEX "Submission_userId_problemId_createdAt_idx" ON "Submission"("userId","problemId","createdAt");
CREATE INDEX "UserProblemProgress_userId_status_lastAttemptAt_idx" ON "UserProblemProgress"("userId","status","lastAttemptAt");
